begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create temporary table tap_results(line text);grant all on tap_results to authenticated;
create function pg_temp.i(n integer) returns uuid language sql immutable as $$select ('91000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
 values(pg_temp.i(301),pg_temp.i(1),'Imported feed','000761','piece','Workbook photo 6','Selling unit not shown',true,true,true,'/products/0123456789abcdef.webp','https://example.com/product','Reference pack');
create function pg_temp.ctx() returns jsonb language sql as $$select jsonb_build_object('organizationId',pg_temp.i(1),'branchId',pg_temp.i(101))$$;
create function pg_temp.login(n integer) returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i(n),'session_id',pg_temp.i(n),'role','authenticated')::text,true)$$;
create function pg_temp.review() returns jsonb language sql as $$select pg_temp.ctx()||jsonb_build_object('productId',pg_temp.i(301),'baseUnit','kg','unitName','Sack (50 kg)','factor','50','price',158000,'cost',120000)$$;
set local role authenticated;
select pg_temp.login(12);
select pg_temp.login(13);
select pg_temp.login(11);
reset role;
set local role authenticated;
reset role;
rollback;
