insert into tap_results select throws_ok($$update public.products set image_path='https://example.com/tracker.png'$$,'23514',null,'Only local audited image paths can be attached');
insert into tap_results select is(public.agri_command('snapshot',pg_temp.ctx())->'products'->0->>'imagePath','/products/0123456789abcdef.webp','Authorized offline snapshot contains photo provenance');
insert into tap_results select is(public.agri_command('snapshot',pg_temp.ctx())->'products'->0->>'catalogNote','Selling unit not shown','Source uncertainty survives snapshot');
insert into tap_results select throws_ok($$select public.agri_command('review_imported_product',pg_temp.review())$$,'42501','Only the owner can confirm an imported product','Cashier cannot confirm a product');
insert into tap_results select throws_ok($$select public.agri_command('record_sale',pg_temp.ctx()||jsonb_build_object('items',jsonb_build_array(jsonb_build_object('productId',pg_temp.i(301)))))$$,'P0001','The owner must confirm the imported price and selling unit before this item can be sold','Missing price cannot become a zero-price sale');
insert into tap_results select throws_ok($$select public.agri_command('review_imported_product',pg_temp.review())$$,'42501',null,'Other organization cannot confirm imported stock');
insert into tap_results select throws_ok($$select public.agri_command('review_imported_product',pg_temp.review()||jsonb_build_object('factor','NaN'))$$,'P0001','Enter a valid stock conversion','Non-finite conversion is rejected');
insert into tap_results select throws_ok($$select public.agri_command('review_imported_product',pg_temp.review()||jsonb_build_object('price',0))$$,'P0001','Enter a positive price and a non-negative actual cost','Owner must enter a positive price');
insert into tap_results select lives_ok($$select public.agri_command('review_imported_product',pg_temp.review())$$,'Owner confirms actual unit, price and cost');
insert into tap_results select is((select base_unit from public.products where id=pg_temp.i(301)),'kg','Actual stock measurement saved');
insert into tap_results select ok((select not price_pending and not setup_pending and not cost_pending from public.products where id=pg_temp.i(301)),'Only a complete confirmation clears all pending flags');
insert into tap_results select is((select count(*)::integer from public.unit_prices where unit_id=pg_temp.i(401)),2,'Original source price stays as an old version');
insert into tap_results select is((select price from public.unit_prices where unit_id=pg_temp.i(401) and version=2),158000::bigint,'Confirmed price remains exact centavos');
insert into public.inventory_movements(organization_id,branch_id,product_id,quantity,kind,source_id,created_by) values(pg_temp.i(1),pg_temp.i(101),pg_temp.i(301),50,'opening',pg_temp.i(601),pg_temp.i(11));
insert into tap_results select throws_ok($$select public.agri_command('review_imported_product',pg_temp.review())$$,'P0001','Selling setup cannot change after stock or sales are recorded. Change its price separately.','Recorded stock prevents conversion changes');
insert into tap_results select is((select quantity::text from public.branch_inventory where product_id=pg_temp.i(301)),'50.000000','Rejected review does not alter stock');
